VALUES ('e44d65bd-76ee-53e8-add2-468afe8137e0', '84d2d7dd-602a-50f2-a08d-4f857a2ff03e', 'a6803a09-9e55-572b-9bf9-d4691f2ba0bd', 'fbd956d9-615b-5d01-a889-c05dd3ece722', 'Display Name', 'The business-facing name by which the party is normally displayed and recognized. Provides a consistent human-readable representation independent of whether the party is a person or organization. Used in forms, search results, documents, transactions, reports, notifications, and user interfaces. It is a presentation identity for the Party and does not replace legal names, person names, or organization registration names stored by specializations. Required so every party can be unambiguously presented to users and business processes. Required — the record cannot be saved while this is empty. Up to 300 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
