VALUES ('629cce67-997d-52c5-80d6-7a826379f4ea', '5052eb45-8c6e-50f5-b73a-15d6a272a58a', '54eab129-8e50-546f-9fec-f3d70e6e012e', 'c1461456-1ff4-551b-8b77-a45dcc0311e0', 'Legal Name', 'Formal legal name of the organization. Used for contracts, invoices, tax, regulatory reporting, and legal documentation. LegalName is distinct from the operational name. Supplies legal presentation and compliance context. Optional when the organization is not a legal entity or the information is not yet known. Up to 300 characters.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
