VALUES ('70aa458b-e049-5563-b757-c7eb4db0309e', '75265f3a-96f6-592e-b980-59d7988e652a', 'c01a0b63-be51-54cf-b072-a76814613956', 'fbd956d9-615b-5d01-a889-c05dd3ece722', 'Id', 'Immutable identity of the inventory event. Used for stock-ledger traceability, audit, reconciliation, integration and investigation. Identifies the event independently of Product, location, quantity and originating transaction. Every receipt, issue, transfer, return, adjustment, reservation and release uses this identity for audit and balance reconciliation. Required. Must be unique: a save is rejected if another Inventory Movement already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
