-- --------------------------------------------------------------------------
-- Inventory Reservation (bus_inventory_reservation)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8ba7b354-dd51-5f45-aa87-20bd7cde931c', 'Inventory Reservation', 'Maintain Inventory Reservation records', 'Create, find and maintain Inventory Reservation records. The list shows every Inventory Reservation you have access to — select a row to open it, or use New to add one. Each row is a single Inventory Reservation, described by 10 fields.

Id is unique: no two Inventory Reservation records may share the same value, and a save that would duplicate one is rejected. Quantity Reserved, Quantity Consumed, Quantity Released, Status, Product, Inventory Location and Inventory Balance must be filled in before the record can be saved.

Every Inventory Reservation points at Product, Inventory Location and Inventory Balance. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Inventory Reservation then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Inventory Reservation with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('38b595a2-91c9-51c2-9e36-2c94d66ed6d8', 'bus_inventory_reservation', 'Inventory Reservation', 'Controls the commitment of available inventory to demand while separating reservation state from physical stock movement. Reservation means stock is committed, not physically moved. Physical movement occurs only when an authorized fulfillment or inventory movement workflow posts it. Sales fulfillment, maintenance demand, allocation, picking, replenishment, production and inventory control. Product identifies stock, InventoryLocation identifies where it is reserved, InventoryBalance supplies available state, and SalesOrderLine supplies one possible demand source. Demand approved → availability checked → reservation created → InventoryBalance reserved/available updated → pick/issue/fulfillment → reservation consumed and InventoryMovement posted. Cancellation/expiry releases reserved quantity. Master or location changes trigger revalidation. Pending → Active → Partially consumed → Consumed, or Active → Released/Cancelled/Expired. Terminal states preserve history. Reservation creation, increase, consumption and release require transactional concurrency control so available inventory cannot be reserved twice. 100 units are available. A SalesOrderLine reserves 30, making 70 available. Picking consumes 10 reserved units and posts the corresponding issue movement; the reservation has 20 remaining. If the location is blocked, the reservation must be transferred or released before the stock can be considered available elsewhere.', 'A', FALSE, FALSE, FALSE, TRUE, '8ba7b354-dd51-5f45-aa87-20bd7cde931c', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1ae140bf-e4c4-5511-920b-98c49be463a6', '8ba7b354-dd51-5f45-aa87-20bd7cde931c', '38b595a2-91c9-51c2-9e36-2c94d66ed6d8', 'Inventory Reservation', 'Shows one Inventory Reservation at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product, Inventory Location and Inventory Balance are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
