-- --------------------------------------------------------------------------
-- Inventory Transfer (bus_inventory_transfer)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fba930f5-3556-5766-afe2-ec15fcb5d2f0', 'Inventory Transfer', 'Maintain Inventory Transfer records', 'Create, find and maintain Inventory Transfer records. The list shows every Inventory Transfer you have access to — select a row to open it, or use New to add one. Each row is a single Inventory Transfer, described by 7 fields.

Id and Transfer Number are unique: no two Inventory Transfer records may share the same value, and a save that would duplicate one is rejected. Transfer Number, Requested Quantity, Status, Product and Source Location must be filled in before the record can be saved.

Every Inventory Transfer points at Product and Lot. Choose the linked record from the lookup on those fields rather than typing an identifier. Inventory Movement, Serial Number and Putaway refer back to Inventory Transfer, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Inventory Transfer then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Inventory Transfer with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b5387191-bd6e-5852-b131-7e7255bafbd5', 'bus_inventory_transfer', 'Inventory Transfer', 'Warehouse/inventory relocation authorization separated from stock ledger events. InventoryTransfer explains why and where stock should move; InventoryMovement records what stock actually changed location. Putaway, replenishment, staging, inter-bin relocation and controlled warehouse transfers. Product/Lot/Serial identify stock; InventoryLocation supplies origin/destination; InventoryMovement provides authoritative physical effect. Planned → released → in progress → completed or cancelled. Release reserves/validates eligible stock where policy requires; execution updates balances only through movements.', 'A', FALSE, FALSE, FALSE, TRUE, 'fba930f5-3556-5766-afe2-ec15fcb5d2f0', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d9f77327-03b8-5b62-bcb2-0ee31c90bfaf', 'fba930f5-3556-5766-afe2-ec15fcb5d2f0', 'b5387191-bd6e-5852-b131-7e7255bafbd5', 'Inventory Transfer', 'Shows one Inventory Transfer at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product and Lot are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ccb5e0d0-5058-5caa-8d25-775a50904414', 'b5387191-bd6e-5852-b131-7e7255bafbd5', 'id', 'Id', 'Stable transfer identity. Identifies one governed relocation independently of stock postings. Warehouse transfer, staging, replenishment and audit. Groups attributable InventoryMovement events. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e4f8cc79-76d1-56cf-9071-c3568c3b475f', 'b5387191-bd6e-5852-b131-7e7255bafbd5', 'transfer_number', 'Transfer Number', 'Human-facing transfer reference. Operational identifier for relocation work. Warehouse execution and reconciliation. Distinct from movement numbers. Required.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('56332b0a-5780-5945-9a32-e340e2231fe9', 'b5387191-bd6e-5852-b131-7e7255bafbd5', 'requested_quantity', 'Requested Quantity', 'Quantity authorized for relocation. Defines transfer demand. Execution and variance reconciliation. Interpreted with Product and traceability identities. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
