INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('33d17932-a76c-5c3f-b3d0-9a88c9036355', 'Packing', 'Maintain Packing records', 'Create, find and maintain Packing records. The list shows every Packing you have access to — select a row to open it, or use New to add one. Each row is a single Packing, described by 5 fields.

Id is unique: no two Packing records may share the same value, and a save that would duplicate one is rejected. Packed Quantity, Status and Handling Unit must be filled in before the record can be saved.

Every Packing points at Picking and Handling Unit. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Packing then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Packing with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d8c81be1-91fe-5997-a5e7-b2ffb10067ad', 'bus_packing', 'Packing', 'Warehouse packaging execution between picking and shipping. Packing establishes physical package composition/readiness; Shipment and InventoryMovement separately govern transport and stock effects. Fulfillment, package labeling, staging, carrier handoff and traceability. Picking supplies goods; HandlingUnit identifies package; Shipment/ShipmentLine supply transport context. Planned → in progress → packed, cancelled or exception.', 'A', FALSE, FALSE, FALSE, TRUE, '33d17932-a76c-5c3f-b3d0-9a88c9036355', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
