INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88a7b546-067b-5c28-8ca4-30109eaa0151', 'Wave', 'Maintain Wave records', 'Create, find and maintain Wave records. The list shows every Wave you have access to — select a row to open it, or use New to add one. Each row is a single Wave, described by 4 fields.

Id and Wave Number are unique: no two Wave records may share the same value, and a save that would duplicate one is rejected. Wave Number, Status and Warehouse must be filled in before the record can be saved.

Every Wave points at Warehouse. Choose the linked record from the lookup on those fields rather than typing an identifier. Putaway and Picking refer back to Wave, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Wave then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Wave with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02746080-de55-5127-bca4-048fc2f65ac1', 'bus_wave', 'Wave', 'Warehouse work-release grouping for coordinated execution. Wave organizes tasks; it does not itself move inventory or fulfill orders. Labor planning, batch/zone picking, putaway and shipping-cutoff execution. Warehouse supplies facility; Picking and Putaway supply executable tasks. Planned to released to in progress to completed or cancelled.', 'A', FALSE, FALSE, FALSE, TRUE, '88a7b546-067b-5c28-8ca4-30109eaa0151', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
