VALUES ('f0b74303-fb35-58f0-b1a3-fbc8e9dbcd4e', 'bus_packaging', 'Packaging', 'Product packaging and pack-quantity master. Packaging describes commercial/logistics containment; HandlingUnit identifies an actual pallet/carton/tote/package occurrence. PIM, procurement, sales, WMS, shipping and labeling. Product defines contents, UOM defines quantity semantics, HandlingUnit represents physical execution instances. Created/activated → revised/retired under controlled master-data change.', 'A', FALSE, FALSE, FALSE, TRUE, '4a021c44-d4ff-56c5-98e5-4f4131ee959a', 'U', TRUE, 'system', 'system', NOW(), NOW())
